def hook(ctx, nb):
    if ctx['action']['tool'] != 'click_action':
        return None
    val = ctx['action']['value_normalized']
    if val != 'buy now':
        return None
    if ctx['predicates']['product_price_over_budget']:
        return {'kind': 'block_and_prompt', 'message': 'Do not buy this item: its current price is over the stated budget. Go back to search/results and choose an in-budget product.'}
    if ctx['predicates']['required_options_unselected']:
        needs = []
        color = ctx['task']['required_color']
        size = ctx['task']['required_size']
        material = ctx['task']['required_material']
        if color:
            needs.append('color ' + str(color))
        if size:
            needs.append('size ' + str(size))
        if material:
            needs.append('material ' + str(material))
        detail = ' the matching visible option(s)'
        if needs:
            detail = ' the required ' + ', '.join(needs) + detail
        return {'kind': 'block_and_prompt', 'message': 'Do not buy yet: a required product option is still unselected' + detail + '. Choose the matching visible option first, then use Buy Now.'}
    return None
